        inline const char* const (*practice_phase_labels(int section, int difficulty))[3]
        {
            switch (section)
            {
            default:
                break;
            case TH15_ST6_BOSS11:
                return practice_TH_SPELL_PHASE2;
            case TH15_ST7_END_S9:
                return practice_TH15_SPELL_PHASE_EXTRA_TIMEOUT;
            case TH15_ST7_END_S10:
                return practice_TH15_SPELL_PHASE_EXTRA_LAST;
            case TH15_ST5_MID1:
                return practice_TH15_ITS_LUNATIC_TIME;
            case TH15_ST3_BOSS1:
                return practice_TH15_ST3_NORMAL1_TYPE;
            case TH15_ST8_AB_TEST:
                return practice_TH15_AB_5PHASE;
            case 10000 + 5 * 100 + 8:
                return practice_TH_PHASE_INF_MODE_TH15_LASERS;
            case 10000 + 5 * 100 + 10:
                return practice_TH_PHASE_INF_MODE;
            case TH15_ST6_STARS:
                return practice_TH_PHASE_INF_MODE;
            case TH15_ST6_BOSS4:
                return practice_TH_SPELL_PHASE1;
            case TH15_ST6_BOSS6:
                if (difficulty>=2)
                    return practice_TH15_ST6_BOSS6_PHASE;
                return nullptr;
            case TH15_ST5_BOSS4:
                return practice_TH_TIMEOUT_SETTING;
            case 10000 + 3 * 100 + 3:
                return practice_TH_STAGE_SKIP_HALF;
            case 10000 + 4 * 100 + 2:
                return practice_TH_STAGE_SKIP_HALF;
            }
            return nullptr;
        }

